<script setup lang="ts">
import StatusProgress from './StatusProgress.vue'
const props=defineProps<{dashboard:any;money:(v:number)=>string;date:(v?:string)=>string}>()
const emit=defineEmits<{filter:[value:string];refresh:[]}>()
const max=(rows:any[],key:string)=>Math.max(...rows.map(row=>Number(row[key])||0),1)
const calendarDays=computed(()=>Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()+i);const key=d.toISOString().slice(0,10);return {key,label:d.toLocaleDateString('en-TZ',{weekday:'short'}),day:d.getDate(),data:props.dashboard?.calendar?.find((x:any)=>x.event_date===key)}}))
const action=(type:string,count:number,text:string)=>({type,count,text})
</script>
<template><section class="metrics"><article><span>MONTHLY VALUE</span><strong>{{money(dashboard?.monthSummary?.[0]?.total)}}</strong><small :class="{up:dashboard?.valueTrend>=0,down:dashboard?.valueTrend<0}">{{dashboard?.valueTrend===null?'No prior-month comparison':`${dashboard.valueTrend>=0?'↑':'↓'} ${Math.abs(dashboard.valueTrend)}% vs last month`}}</small></article><article><span>PAID TOTAL</span><strong>{{money(dashboard?.paidTotal||0)}}</strong><small>Payments collected</small></article><article><span>OUTSTANDING BALANCE</span><strong>{{money(dashboard?.outstandingTotal||0)}}</strong><small>Remaining client balances</small></article><article><span>ORDERS TODAY</span><strong>{{dashboard?.recordsToday||0}}</strong><small>Created today</small></article><article><span>ACTIVE ORDERS</span><strong>{{dashboard?.activeRecords||0}}</strong><small>Current orders</small></article><article><span>UPCOMING EVENTS</span><strong>{{dashboard?.upcomingEvents?.length||0}}</strong><small>Next 7 days</small></article></section>
<section class="grid"><article class="card"><h2>Order Status</h2><StatusProgress v-for="s in ['Pending','Confirmed','Cancelled'].map(name=>dashboard?.byStatus?.find((x:any)=>x.name===name)||{name,color:name==='Cancelled'?'#dc2626':name==='Confirmed'?'#0ea5e9':'#d97706',count:0})" :key="s.name" :name="s.name" :color="s.color" :count="s.count" :total="dashboard?.activeRecords||0"/></article>
<article class="card"><h2>Next 7 days</h2><div class="calendar"><div v-for="d in calendarDays" :key="d.key" :class="{today:d.key===new Date().toISOString().slice(0,10)}"><small>{{d.label}}</small><b>{{d.day}}</b><em v-if="d.data">{{d.data.count}}</em></div></div></article>
<article class="card full"><div class="heading"><div><h2>Upcoming events</h2><small>What needs attention this week</small></div></div><button v-for="event in (dashboard?.upcomingEvents||[]).slice(0,5)" :key="event.id" class="event" @click="emit('filter','')"><span><b>{{date(event.event_date)}}</b><small>{{event.location||'Location not set'}}</small></span><span><b>{{event.client_name}}</b><small>{{event.status_name}}</small></span><strong>{{money(event.grand_total_minor)}}</strong></button><p v-if="!dashboard?.upcomingEvents?.length" class="empty">No events in the next 7 days.</p></article>
<article class="card"><h2>Outstanding clients</h2><button v-for="client in dashboard?.outstandingClients||[]" :key="client.client_name" class="action" @click="emit('filter','unpaid')"><span><b>{{client.client_name}}</b><small>{{client.orders}} outstanding orders</small></span><strong>{{money(client.balance_minor)}}</strong></button><p v-if="!dashboard?.outstandingClients?.length" class="empty">No outstanding balances.</p></article><article class="card"><h2>Top clients</h2><div v-for="client in dashboard?.topClients||[]" :key="client.client_name" class="rank"><span>{{client.client_name}}</span><i><em :style="{width:`${Number(client.total)/max(dashboard.topClients,'total')*100}%`}"></em></i><b>{{money(client.total)}}</b></div></article></section><small class="fresh">Updated {{dashboard?.generatedAt?new Date(dashboard.generatedAt).toLocaleTimeString():''}}</small></template>
<style scoped>.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:18px}.metrics article,.card{background:var(--card);border:1px solid var(--border);border-radius:12px;padding:20px}.metrics span,.metrics small,small{display:block;color:var(--muted)}.metrics strong{display:block;font-size:25px;margin:9px 0}.up{color:#26734d!important}.down{color:#a14232!important}.grid{display:grid;grid-template-columns:1.5fr 1fr;gap:16px}.full{grid-column:span 2}.heading{display:flex;justify-content:space-between}.heading h2,.card h2{margin:0;font-size:16px}.heading button{border:0;background:none;color:var(--brand);font-weight:800;cursor:pointer}svg{width:100%;height:145px;margin-top:14px;background:#f7f2e8;border-radius:8px}rect{fill:var(--brand)}.line-chart .line{stroke:var(--brand);stroke-width:3;vector-effect:non-scaling-stroke}.line-chart circle{fill:#fff;stroke:var(--brand);stroke-width:2}.grid-lines line{stroke:#d9e1dc;stroke-width:1}.action,.event{width:100%;display:flex;align-items:center;gap:10px;border:0;border-bottom:1px solid var(--border);background:none;padding:12px 0;text-align:left;cursor:pointer}.action b{margin-left:auto}.action i{color:var(--brand);font-style:normal;font-weight:700}.calendar{display:grid;grid-template-columns:repeat(7,1fr);gap:5px;margin-top:16px}.calendar>div{text-align:center;padding:9px 2px;border-radius:8px;background:#f7f2e8}.calendar .today{background:var(--brand);color:#fff}.calendar .today small{color:#fff}.calendar b{display:block}.calendar em{display:inline-grid;place-items:center;margin-top:5px;width:18px;height:18px;border-radius:50%;background:var(--tan);color:#fff;font-size:10px;font-style:normal}.event span:nth-child(2){flex:1}.event strong{white-space:nowrap}.rank{display:grid;grid-template-columns:1fr 1.5fr auto;gap:8px;align-items:center;margin:13px 0;font-size:12px}.rank i{height:7px;border-radius:99px;background:#eee6d9;overflow:hidden}.rank em{display:block;height:100%;background:var(--rust)}.audit{display:flex;gap:9px;margin:13px 0}.audit>i{width:8px;height:8px;border-radius:50%;background:var(--tan);margin-top:5px}.audit small{font-size:11px}.empty{color:var(--muted)}.fresh{margin-top:14px;text-align:right}@media(max-width:900px){.metrics{grid-template-columns:1fr 1fr}.grid{grid-template-columns:1fr}.full{grid-column:span 1}}@media(max-width:520px){.metrics{grid-template-columns:1fr}}</style>
